// Extract minimal fields from Telegram message

function extractUrls(text) {
  if (!text) return [];
  const regex = /https?:\/\/[^\s)"']+/g;
  const m = text.match(regex);
  return m ? Array.from(new Set(m)) : [];
}

return items.map((item) => {
  const msg = item.json.message ?? {};
  const text = String(msg.text ?? '');
  const title = text.split(/
/)[0] || 'Telegram signal';
  const description = text;
  const sourceUrl = '';
  const rawUrls = extractUrls(text);
  return { json: { title, description, source_url: sourceUrl, raw_urls: rawUrls } };
});

// Normalize + tags (inline v1, same rules as RSS workflow)

const TRACKING_PARAMS = ['utm_source','utm_medium','utm_campaign','utm_term','utm_content','ref'];
const SHORT_HOSTS = new Set(['t.co','bit.ly','tinyurl.com']);

function normalizeUrl(url) {
  const u = new URL(url);
  u.hash = '';
  for (const k of TRACKING_PARAMS) u.searchParams.delete(k);
  if (u.protocol === 'http:') u.protocol = 'https:';
  const s = u.toString();
  return s.endsWith('/') ? s : s + '/';
}

function isLikelyShortLink(url) {
  try {
    const u = new URL(url);
    return SHORT_HOSTS.has(u.hostname);
  } catch {
    return false;
  }
}

function tagsFromText(text) {
  const t = (text || '').toLowerCase();
  const tags = [];
  if (/(solana|\bsol\b)/.test(t)) tags.push('Chain:Solana');
  if (/(ethereum|\beth\b)/.test(t)) tags.push('Chain:Ethereum');
  if (/testnet|faucet/.test(t)) tags.push('Type:Testnet');
  if (/stake|staking|deposit/.test(t)) tags.push('Type:Stake');
  if (/defi|swap|dex/.test(t)) tags.push('Sector:DeFi');
  if (/gamefi|game|guild/.test(t)) tags.push('Sector:GameFi');
  if (/airdrop/.test(t)) tags.push('Signal:Airdrop');
  return Array.from(new Set(tags));
}

return items
  .map((item) => {
    const title = String(item.json.title ?? '').trim();
    const description = String(item.json.description ?? '').trim();
    const sourceUrl = String(item.json.source_url ?? '').trim();
    const rawUrls = Array.isArray(item.json.raw_urls) ? item.json.raw_urls : [];

    const text = `${title}\n${description}\n${sourceUrl}`;
    const candidate = rawUrls.find((u) => !isLikelyShortLink(u));
    if (!candidate) return null;

    let projectUrl;
    try {
      projectUrl = normalizeUrl(candidate);
    } catch {
      return null;
    }

    return {
      json: {
        title: title || projectUrl,
        description: description || title || '',
        source_url: sourceUrl || projectUrl,
        project_url: projectUrl,
        tags: tagsFromText(text),
        status: 'active'
      }
    };
  })
  .filter(Boolean);
